			/**
			 * 서비스의뢰접수 주민번호 값 여부에 따라 서비스접수 결과 저장시 성별 선택여부를 위하여 값 여부를 확인함
			 * <필수체크요망>
			 * @param {String} rrnoVal
			 */
			function rrnoValChk(rrnoVal){

			    /* 서비스의뢰접수 주민번호 여부(주민번호는 필수가 아님)*/
			    // 대상자주민번호가 필수가 아니기 때문에 주민번호가 들어오지 않을 경우 서비스의뢰접수결과 저장시 성별을 선택해야하기위해 각각 readOnly 설정
			    // 주민번호가 들어올경우는 주민번호 7번째 자리로 남,여 성별 구분하여 설정         
			    if (! ValueUtil.isNull(rrnoVal) || rrnoVal != "") {
			        sRrnoValYn = "Y";
			    }else if(ValueUtil.isNull(rrnoVal) || rrnoVal == ""){
			        sRrnoValYn = "N";
			    }
			    return  sRrnoValYn;   
			}

			/** 주민번호에서 성별을 확인하여 성별코드 return (공통코드[남자 : M , 여자 : F])
			 * 주민번호 7번째 자리 정리해드립니다.
			    1 : 1900~1999년도 태어남 남자, 내국인
			    2 : 1900~1999년도 태어남 여자, 내국인
			    3 : 2000년대출생자 남자, 내국인
			    4 : 2000년대출생자 여자, 내국인
			    5 : 1900~1999년도 태어남 남자, 외국인
			    6 : 1900~1999년도 태어남 여자, 외국인
			    7 : 2000년대출생자 남자, 외국인
			    8 : 2000년대출생자 여자, 외국인
			 * @param {String} rrnoVal
			 */
			function rrnoSxdcChk(rrnoVal){

			    if ( ValueUtil.isNull(rrnoVal) ) return false;
			    var vcSxdcCd = "";
			    
			    // 주민번호 7번째 자리 
			    var iSxdcNum = Number(rrnoVal.charAt(6));
			    switch(iSxdcNum){
			        case 1 : case 3 : case 5 : case 7 :
			            vcSxdcCd = "M";
			            break;
			        case 2 : case 4 : case 6 : case 8 : 
			            vcSxdcCd = "F";
			            break;   
			    }
			    return vcSxdcCd;
			}

			/** 주민번호에서 생년월일을 확인하여 생년월일 8자리 return
			 * @param {String} rrnoVal
			 */
			function rrnoBrdtChk(rrnoVal){

			    if ( ValueUtil.isNull(rrnoVal) ) return false;
			    var trprBrdt = "";
			    var year     =  0;
			    
			    var iRrnoBrdtNum = rrnoVal.substring(0, 6);        // 생년월일 6자리
			    var iSxdcNum     = Number(rrnoVal.charAt(6));              // 성별구분
			    
			    switch(iSxdcNum){
			         // 1900년 ~ 1999년
			        case 1 : case 2 : case 5 : case 6 :
			            year = 19;
			            break;
			        // 2000년대    
			        case 3 : case 4 : case 7 : case 8 : 
			            year = 20;
			            break;
			    }
			    trprBrdt = year + iRrnoBrdtNum.toString();

			    return trprBrdt;
			}

